/**
 * 自研视频播放器 - nice-video.css
 * 简化版自定义视频播放器，修复时长显示问题
 * 用法：给 .nice-video-container 的 div 加上 data-src="视频地址"
 */

:root {
    --nv-pink: #FB7299;
    --nv-blue: #00A1D6;
    --nv-bg: rgba(0, 0, 0, 0.85);
}

.nice-video-container {
    position: relative;
    width: 100%;
    max-width: 800px;
    margin: 20px auto;
    border-radius: 16px;
    overflow: hidden;
    background: linear-gradient(135deg, #1a1a2e, #16213e);
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
}

.nice-video-container video {
    width: 100%;
    height: auto;
    display: block;
    border-radius: 16px;
    cursor: pointer;
}

/* 中央播放按钮 */
.nice-video-play-btn {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 80px;
    height: 80px;
    background: linear-gradient(135deg, var(--nv-pink), var(--nv-blue));
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 8px 30px rgba(251, 114, 153, 0.5);
    transition: all 0.3s ease;
    cursor: pointer;
    z-index: 10;
    border: none;
    outline: none;
}

.nice-video-play-btn:hover {
    transform: translate(-50%, -50%) scale(1.1);
    box-shadow: 0 12px 40px rgba(251, 114, 153, 0.6);
}

.nice-video-play-btn i {
    color: white;
    font-size: 2rem;
    margin-left: 4px;
}

.nice-video-container.playing .nice-video-play-btn {
    opacity: 0;
    pointer-events: none;
}

.nice-video-container:hover .nice-video-play-btn {
    opacity: 1;
}

/* 控制栏 */
.nice-video-controls {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    background: linear-gradient(to top, var(--nv-bg), transparent);
    padding: 40px 15px 15px;
    display: flex;
    align-items: center;
    gap: 12px;
    opacity: 0;
    transition: opacity 0.3s ease;
    z-index: 5;
}

.nice-video-container:hover .nice-video-controls,
.nice-video-container.controls-visible .nice-video-controls {
    opacity: 1;
}

/* 控制按钮 */
.nice-video-btn {
    background: none;
    border: none;
    color: white;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 8px;
    border-radius: 6px;
    transition: background 0.2s;
    display: flex;
    align-items: center;
    justify-content: center;
    min-width: 36px;
    height: 36px;
}

.nice-video-btn:hover {
    background: rgba(255, 255, 255, 0.2);
}

/* 进度条容器 */
.nice-video-progress {
    flex: 1;
    height: 24px;
    display: flex;
    align-items: center;
    cursor: pointer;
    padding: 8px 0;
}

.nice-video-progress-bar {
    width: 100%;
    height: 6px;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 3px;
    position: relative;
    overflow: visible;
}

.nice-video-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--nv-pink), var(--nv-blue));
    border-radius: 3px;
    width: 0%;
    transition: width 0.1s linear;
    position: relative;
}

.nice-video-progress-handle {
    position: absolute;
    top: 50%;
    left: 0%;
    transform: translate(-50%, -50%);
    width: 14px;
    height: 14px;
    background: white;
    border-radius: 50%;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
    opacity: 0;
    transition: opacity 0.2s;
}

.nice-video-progress:hover .nice-video-progress-handle {
    opacity: 1;
}

/* 时间显示 */
.nice-video-time {
    color: white;
    font-size: 0.85rem;
    font-family: 'MaokenAssortedSans', 'Monaco', 'Menlo', monospace;
    min-width: 100px;
    text-align: center;
    white-space: nowrap;
}

/* 音量控制 */
.nice-video-volume {
    display: flex;
    align-items: center;
    gap: 6px;
}

.nice-video-volume-slider {
    width: 60px;
    height: 6px;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 3px;
    cursor: pointer;
    position: relative;
}

.nice-video-volume-fill {
    height: 100%;
    background: white;
    border-radius: 3px;
    width: 70%;
}

/* 加载动画 */
.nice-video-loading {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 50px;
    height: 50px;
    border: 4px solid rgba(255,255,255,0.3);
    border-top-color: white;
    border-radius: 50%;
    animation: nv-spin 0.8s linear infinite;
    z-index: 5;
    display: none;
}

.nice-video-container.loading .nice-video-loading {
    display: block;
}

@keyframes nv-spin {
    to { transform: translate(-50%, -50%) rotate(360deg); }
}

/* 全屏样式 */
.nice-video-container:fullscreen,
.nice-video-container:-webkit-full-screen {
    border-radius: 0;
    max-width: 100%;
}

.nice-video-container:fullscreen video,
.nice-video-container:-webkit-full-screen video {
    border-radius: 0;
}

/* 断网提示覆盖层 */
.nv-network-disconnected {
    display: none;
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.75);
    color: #fff;
    align-items: center;
    justify-content: center;
    z-index: 20;
    font-size: 1rem;
    flex-direction: column;
    gap: 10px;
    pointer-events: none;
}

.nv-network-disconnected i {
    font-size: 2.5rem;
    color: #f59e0b;
    margin-bottom: 4px;
}

/**
 * 自研视频播放器 - nice-video.js
 * 简化版，修复时长00:00 bug
 * 用法：
 *   <div class="nice-video-container" data-src="视频地址">
 *       <video preload="metadata"></video>
 *   </div>
 *   然后调用 NiceVideo.initAll() 初始化
 */

(function(global) {
    'use strict';

    /**
     * 初始化单个播放器
     */
    function initOne(container) {
        if (container.__nvInitialized) return;
        container.__nvInitialized = true;

        const video = container.querySelector('video');
        if (!video) {
            console.error('[NiceVideo] 找不到 video 元素');
            return;
        }

        // 获取视频源并设置
        const src = container.dataset.src || '';
        if (src && !video.src) {
            video.src = src;
            console.log('[NiceVideo] 设置视频源:', src);
        }

        // 创建控制栏（如果不存在）
        let controls = container.querySelector('.nice-video-controls');
        if (!controls) {
            controls = createControls();
            container.appendChild(controls);
        }

        // 创建中央播放按钮（如果不存在）
        let playBtn = container.querySelector('.nice-video-play-btn');
        if (!playBtn) {
            playBtn = document.createElement('button');
            playBtn.className = 'nice-video-play-btn';
            playBtn.innerHTML = '<i class="fas fa-play"></i>';
            container.appendChild(playBtn);
        }

        // 创建加载指示器（如果不存在）
        let loading = container.querySelector('.nice-video-loading');
        if (!loading) {
            loading = document.createElement('div');
            loading.className = 'nice-video-loading';
            container.appendChild(loading);
        }

        // 获取控制栏元素
        const playPauseBtn = controls.querySelector('.nv-play-pause');
        const progressBar = controls.querySelector('.nice-video-progress-bar');
        const progressFill = controls.querySelector('.nice-video-progress-fill');
        const progressHandle = controls.querySelector('.nice-video-progress-handle');
        const timeDisplay = controls.querySelector('.nice-video-time');
        const volumeBtn = controls.querySelector('.nv-volume');
        const volumeSlider = controls.querySelector('.nice-video-volume-slider');
        const volumeFill = controls.querySelector('.nice-video-volume-fill');
        const fullscreenBtn = controls.querySelector('.nv-fullscreen');

        // 状态
        let isPlaying = false;
        let isDraggingProgress = false;
        let isDraggingVolume = false;
        let isMuted = false;
        let lastVolume = 0.7;
        let hideControlsTimer = null;

        // ===== 播放/暂停 =====
        function togglePlay(e) {
            if (e) e.stopPropagation();

            console.log('[NiceVideo] togglePlay, paused:', video.paused, 'readyState:', video.readyState);

            if (video.paused || video.ended) {
                const promise = video.play();
                if (promise !== undefined) {
                    promise.then(() => {
                        console.log('[NiceVideo] 播放成功');
                        isPlaying = true;
                        container.classList.add('playing');
                        container.classList.add('controls-visible');
                        updatePlayPauseBtn();
                    }).catch(err => {
                        // AbortError 由用户主动暂停引起，静默忽略
                        if (err.name === 'AbortError') return;
                        console.error('[NiceVideo] 播放失败:', err);
                    });
                }
            } else {
                video.pause();
                isPlaying = false;
                container.classList.remove('playing');
                updatePlayPauseBtn();
            }
        }

        function updatePlayPauseBtn() {
            if (!playPauseBtn) return;
            playPauseBtn.innerHTML = isPlaying 
                ? '<i class="fas fa-pause"></i>' 
                : '<i class="fas fa-play"></i>';
        }

        if (playBtn) playBtn.addEventListener('click', togglePlay);
        if (playPauseBtn) playPauseBtn.addEventListener('click', togglePlay);

        video.addEventListener('click', function(e) {
            if (!e.target.closest('.nice-video-controls')) {
                togglePlay(e);
            }
        });

        // ===== 进度条 =====
        function updateProgress() {
            if (!isDraggingProgress && video.duration && isFinite(video.duration)) {
                const percent = (video.currentTime / video.duration) * 100;
                if (progressFill) progressFill.style.width = percent + '%';
                if (progressHandle) progressHandle.style.left = percent + '%';
            }
        }

        function updateTimeDisplay() {
            if (!timeDisplay) return;
            const current = formatTime(video.currentTime);
            const duration = formatTime(video.duration);
            timeDisplay.textContent = current + ' / ' + duration;
        }

        function formatTime(seconds) {
            if (isNaN(seconds) || !isFinite(seconds) || seconds < 0) return '00:00';
            const mins = Math.floor(seconds / 60);
            const secs = Math.floor(seconds % 60);
            return String(mins).padStart(2, '0') + ':' + String(secs).padStart(2, '0');
        }

        if (progressBar) {
            progressBar.addEventListener('click', function(e) {
                e.stopPropagation();
                if (!video.duration) {
                    console.warn('[NiceVideo] 视频时长未加载，无法跳转');
                    return;
                }
                const rect = progressBar.getBoundingClientRect();
                const percent = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
                video.currentTime = percent * video.duration;
            });
        }

        // 进度条拖动
        function onProgressMouseDown(e) {
            if (e.target.closest('.nice-video-progress-handle') || e.target === progressBar || e.target === progressFill) {
                isDraggingProgress = true;
                document.body.style.userSelect = 'none';
                e.preventDefault();
                e.stopPropagation();
            }
        }

        if (progressBar) {
            progressBar.addEventListener('mousedown', onProgressMouseDown);
        }

        // ===== 音量控制 =====
        function updateVolumeDisplay() {
            const vol = isMuted ? 0 : video.volume;
            if (volumeFill) volumeFill.style.width = (vol * 100) + '%';
            if (!volumeBtn) return;
            if (isMuted || vol === 0) {
                volumeBtn.innerHTML = '<i class="fas fa-volume-mute"></i>';
            } else if (vol < 0.5) {
                volumeBtn.innerHTML = '<i class="fas fa-volume-down"></i>';
            } else {
                volumeBtn.innerHTML = '<i class="fas fa-volume-up"></i>';
            }
        }

        function setVolume(percent) {
            percent = Math.max(0, Math.min(1, percent));
            video.volume = percent;
            lastVolume = percent;
            isMuted = percent === 0;
            updateVolumeDisplay();
        }

        if (volumeBtn) {
            volumeBtn.addEventListener('click', function(e) {
                e.stopPropagation();
                if (isMuted || video.volume === 0) {
                    video.volume = lastVolume || 0.7;
                    isMuted = false;
                } else {
                    lastVolume = video.volume;
                    video.volume = 0;
                    isMuted = true;
                }
                updateVolumeDisplay();
            });
        }

        if (volumeSlider) {
            volumeSlider.addEventListener('click', function(e) {
                e.stopPropagation();
                const rect = volumeSlider.getBoundingClientRect();
                const percent = (e.clientX - rect.left) / rect.width;
                setVolume(percent);
            });

            volumeSlider.addEventListener('mousedown', function(e) {
                isDraggingVolume = true;
                e.preventDefault();
                e.stopPropagation();
            });
        }

        // 全局鼠标事件
        function onMouseMove(e) {
            if (isDraggingProgress && progressBar) {
                const rect = progressBar.getBoundingClientRect();
                let percent = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
                video.currentTime = percent * video.duration;
            }
            if (isDraggingVolume && volumeSlider) {
                const rect = volumeSlider.getBoundingClientRect();
                const percent = (e.clientX - rect.left) / rect.width;
                setVolume(percent);
            }
        }

        function onMouseUp() {
            isDraggingProgress = false;
            isDraggingVolume = false;
            document.body.style.userSelect = '';
        }

        document.addEventListener('mousemove', onMouseMove);
        document.addEventListener('mouseup', onMouseUp);

        // 初始化音量
        video.volume = lastVolume;
        updateVolumeDisplay();

        // ===== 全屏 =====
        function toggleFullscreen(e) {
            if (e) e.stopPropagation();

            const fsEl = document.fullscreenElement 
                || document.webkitFullscreenElement 
                || document.mozFullScreenElement 
                || document.msFullscreenElement;

            if (fsEl) {
                if (document.exitFullscreen) document.exitFullscreen();
                else if (document.webkitExitFullscreen) document.webkitExitFullscreen();
                else if (document.mozCancelFullScreen) document.mozCancelFullScreen();
                else if (document.msExitFullscreen) document.msExitFullscreen();
            } else {
                const target = video;
                if (target.requestFullscreen) target.requestFullscreen();
                else if (target.webkitRequestFullscreen) target.webkitRequestFullscreen();
                else if (target.mozRequestFullScreen) target.mozRequestFullScreen();
                else if (target.msRequestFullscreen) target.msRequestFullscreen();
            }
        }

        if (fullscreenBtn) {
            fullscreenBtn.addEventListener('click', toggleFullscreen);
        }

        function updateFullscreenBtn() {
            const isFs = !!(document.fullscreenElement || document.webkitFullscreenElement);
            if (fullscreenBtn) {
                fullscreenBtn.innerHTML = isFs 
                    ? '<i class="fas fa-compress"></i>' 
                    : '<i class="fas fa-expand"></i>';
            }
        }

        document.addEventListener('fullscreenchange', updateFullscreenBtn);
        document.addEventListener('webkitfullscreenchange', updateFullscreenBtn);

        // ===== 视频事件 =====
        video.addEventListener('loadedmetadata', function() {
            console.log('[NiceVideo] 元数据加载完成，时长:', video.duration);
            updateTimeDisplay();
            container.classList.remove('loading');
        });

        video.addEventListener('timeupdate', function() {
            updateProgress();
            updateTimeDisplay();
        });

        video.addEventListener('play', function() {
            isPlaying = true;
            container.classList.add('playing');
            updatePlayPauseBtn();
        });

        video.addEventListener('pause', function() {
            isPlaying = false;
            container.classList.remove('playing');
            updatePlayPauseBtn();
        });

        video.addEventListener('ended', function() {
            isPlaying = false;
            container.classList.remove('playing');
            updatePlayPauseBtn();
        });

        video.addEventListener('waiting', function() {
            container.classList.add('loading');
        });

        video.addEventListener('canplay', function() {
            container.classList.remove('loading');
        });

        // 如果视频已经有元数据，立即更新
        if (video.readyState >= 1) {
            console.log('[NiceVideo] 视频已有元数据，时长:', video.duration);
            updateTimeDisplay();
        }

        // ===== 显示/隐藏控制栏 =====
        container.addEventListener('mousemove', function() {
            container.classList.add('controls-visible');
            clearTimeout(hideControlsTimer);
            if (isPlaying) {
                hideControlsTimer = setTimeout(function() {
                    container.classList.remove('controls-visible');
                }, 3000);
            }
        });

        container.addEventListener('mouseleave', function() {
            if (isPlaying) {
                hideControlsTimer = setTimeout(function() {
                    container.classList.remove('controls-visible');
                }, 1000);
            }
        });

        // ===== 双击全屏 =====
        video.addEventListener('dblclick', function(e) {
            e.preventDefault();
            toggleFullscreen(e);
        });

        // ===== 网络状态监听、断网提示与自动恢复 =====
        var _retryCount = 0;
        var _maxRetries = 3;
        var _baseDelay = 1000;
        var _maxDelay = 30000;
        var _retryTimer = null;
        var _isDisconnected = false;

        // 创建断网提示覆盖层
        var _netOverlay = container.querySelector('.nv-network-disconnected');
        if (!_netOverlay) {
            _netOverlay = document.createElement('div');
            _netOverlay.className = 'nv-network-disconnected';
            _netOverlay.innerHTML = '<i class="fas fa-wifi-slash"></i> 网络已断开，请检查连接';
            container.appendChild(_netOverlay);
        }

        function _showDisconnected() {
            _isDisconnected = true;
            _netOverlay.style.display = 'flex';
            video.pause();
        }

        function _hideDisconnected() {
            _isDisconnected = false;
            _netOverlay.style.display = 'none';
            _retryCount = 0;
        }

        // 断网恢复监听
        window.addEventListener('online', function _onOnline() {
            if (_isDisconnected) {
                console.log('[NiceVideo] 网络已恢复，重新加载视频');
                _hideDisconnected();
                video.load();
                video.play().catch(function() {});
            }
        });

        window.addEventListener('offline', function _onOffline() {
            if (!navigator.onLine) {
                _showDisconnected();
            }
        });

        // 视频网络错误重试（指数退避）
        video.addEventListener('error', function _onVideoError() {
            if (!navigator.onLine) {
                _showDisconnected();
                return;
            }

            var mediaError = video.error;
            var isNetworkError = mediaError && (
                mediaError.code === MediaError.MEDIA_ERR_NETWORK ||
                (mediaError.message && mediaError.message.indexOf('Network') >= 0) ||
                (mediaError.message && mediaError.message.indexOf('ERR_INTERNET_DISCONNECTED') >= 0)
            );

            if (isNetworkError) {
                if (_retryCount < _maxRetries) {
                    var delay = Math.min(
                        _baseDelay * Math.pow(2, _retryCount),
                        _maxDelay
                    );
                    _retryCount++;
                    console.log('[NiceVideo] 网络错误，第 ' + _retryCount + '/' + _maxRetries + ' 次重试，等待 ' + delay + 'ms');
                    clearTimeout(_retryTimer);
                    _retryTimer = setTimeout(function() {
                        video.load();
                    }, delay);
                } else {
                    console.error('[NiceVideo] 重试次数已达上限');
                    _retryCount = 0;
                    var evt = new CustomEvent('playererror', {
                        detail: { type: 'network', message: '视频加载失败，请稍后重试' }
                    });
                    container.dispatchEvent(evt);
                }
            }
        });

        // 初始化
        updateTimeDisplay();
        video.load();
    }

    /**
     * 创建控制栏
     */
    function createControls() {
        const controls = document.createElement('div');
        controls.className = 'nice-video-controls';
        controls.innerHTML = `
            <button class="nice-video-btn nv-play-pause" title="播放/暂停">
                <i class="fas fa-play"></i>
            </button>
            <div class="nice-video-progress">
                <div class="nice-video-progress-bar">
                    <div class="nice-video-progress-fill"></div>
                    <div class="nice-video-progress-handle"></div>
                </div>
            </div>
            <span class="nice-video-time">00:00 / 00:00</span>
            <div class="nice-video-volume">
                <button class="nice-video-btn nv-volume" title="音量">
                    <i class="fas fa-volume-up"></i>
                </button>
                <div class="nice-video-volume-slider">
                    <div class="nice-video-volume-fill"></div>
                </div>
            </div>
            <button class="nice-video-btn nv-fullscreen" title="全屏">
                <i class="fas fa-expand"></i>
            </button>
        `;
        return controls;
    }

    // ===== 公共 API =====
    global.NiceVideo = {
        init: function(container) {
            if (!container) {
                console.error('[NiceVideo] container is required');
                return;
            }
            initOne(container);
        },

        initAll: function() {
            document.querySelectorAll('.nice-video-container').forEach(function(container) {
                initOne(container);
            });
        }
    };

    // 自动初始化
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', function() {
            global.NiceVideo.initAll();
        });
    } else {
        global.NiceVideo.initAll();
    }

})(window);

/**
 * 视频播放器样式 - vid/video-player.css
 * 对应 vid/video-player.js
 * 使用 class: .video-player-container
 */

:root {
    --vp-pink: #FB7299;
    --vp-blue: #00A1D6;
}

.video-player-container {
    position: relative;
    width: 100%;
    max-width: 800px;
    margin: 0 auto;
    border-radius: 16px;
    overflow: hidden;
    background: linear-gradient(135deg, #1a1a2e, #16213e);
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
    font-family: 'MaokenAssortedSans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.video-player-container video {
    width: 100%;
    height: auto;
    display: block;
    cursor: pointer;
}

/* 封面层 */
.video-poster {
    position: absolute;
    top: 0; left: 0;
    width: 100%; height: 100%;
    cursor: pointer;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #1a1a2e;
    background-size: cover;
    background-position: center;
}

.video-poster.hidden {
    display: none;
}

.video-player-container.playing .video-poster {
    display: none;
}

/* 中央播放按钮 */
.play-button {
    position: absolute;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    width: 72px; height: 72px;
    background: linear-gradient(135deg, var(--vp-pink), var(--vp-blue));
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 8px 30px rgba(251, 114, 153, 0.5);
    transition: transform 0.3s, box-shadow 0.3s;
    z-index: 3;
    cursor: pointer;
    border: none;
    outline: none;
}

.play-button:hover {
    transform: translate(-50%, -50%) scale(1.1);
    box-shadow: 0 12px 40px rgba(251, 114, 153, 0.6);
}

.play-button i {
    color: white;
    font-size: 1.8rem;
    margin-left: 4px;
}

/* 控制栏 */
.video-controls {
    position: absolute;
    bottom: 0; left: 0; right: 0;
    background: linear-gradient(to top, rgba(0,0,0,0.9), transparent);
    padding: 40px 15px 12px;
    display: flex;
    align-items: center;
    gap: 10px;
    opacity: 0;
    transition: opacity 0.3s;
    z-index: 4;
}

.video-player-container:hover .video-controls,
.video-player-container.playing .video-controls,
.video-player-container.controls-visible .video-controls {
    opacity: 1;
}

/* 按钮 */
.vp-control-btn {
    background: none;
    border: none;
    color: white;
    font-size: 1rem;
    cursor: pointer;
    padding: 8px;
    border-radius: 6px;
    transition: background 0.2s;
    display: flex;
    align-items: center;
    justify-content: center;
    min-width: 36px;
    height: 36px;
    flex-shrink: 0;
}

.vp-control-btn:hover {
    background: rgba(255, 255, 255, 0.2);
}

/* 进度条 */
.vp-progress-container {
    flex: 1;
    height: 24px;
    display: flex;
    align-items: center;
    cursor: pointer;
    padding: 8px 0;
}

.vp-progress-bar {
    width: 100%;
    height: 6px;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 3px;
    position: relative;
    overflow: visible;
}

.vp-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--vp-pink), var(--vp-blue));
    border-radius: 3px;
    width: 0%;
    transition: width 0.1s linear;
    position: relative;
}

.vp-progress-handle {
    position: absolute;
    top: 50%; left: 0%;
    transform: translate(-50%, -50%);
    width: 14px; height: 14px;
    background: white;
    border-radius: 50%;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
    opacity: 0;
    transition: opacity 0.2s;
}

.vp-progress-container:hover .vp-progress-handle {
    opacity: 1;
}

/* 时间 */
.vp-time-display {
    color: white;
    font-size: 0.8rem;
    font-family: 'MaokenAssortedSans', 'Monaco', 'Menlo', monospace;
    min-width: 90px;
    text-align: center;
    white-space: nowrap;
    flex-shrink: 0;
}

/* 音量 */
.vp-volume-container {
    display: flex;
    align-items: center;
    gap: 6px;
    flex-shrink: 0;
}

.vp-volume-slider {
    width: 70px;
    height: 6px;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 3px;
    cursor: pointer;
    position: relative;
}

.vp-volume-fill {
    height: 100%;
    background: white;
    border-radius: 3px;
    width: 70%;
}

/* 加载动画 */
.vp-loading {
    position: absolute;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    width: 50px; height: 50px;
    border: 4px solid rgba(255,255,255,0.3);
    border-top-color: white;
    border-radius: 50%;
    animation: vp-spin 0.8s linear infinite;
    z-index: 5;
    display: none;
}

.video-player-container.loading .vp-loading {
    display: block;
}

@keyframes vp-spin {
    to { transform: translate(-50%, -50%) rotate(360deg); }
}

/* 全屏 */
.video-player-container:fullscreen,
.video-player-container:-webkit-full-screen {
    border-radius: 0;
    max-width: 100%;
}

/* 响应式 */
@media (max-width: 768px) {
    .play-button { width: 56px; height: 56px; }
    .play-button i { font-size: 1.4rem; }
    .video-controls { padding: 30px 10px 10px; gap: 8px; }
    .vp-control-btn { min-width: 30px; height: 30px; font-size: 0.9rem; }
    .vp-time-display { font-size: 0.72rem; min-width: 76px; }
    .vp-volume-slider { width: 50px; }
}

@media (max-width: 480px) {
    .vp-volume-container { display: none; }
}

/* 断网提示覆盖层 */
.vp-network-disconnected {
    display: none;
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.75);
    color: #fff;
    align-items: center;
    justify-content: center;
    z-index: 20;
    font-size: 1rem;
    flex-direction: column;
    gap: 10px;
    pointer-events: none;
}

.vp-network-disconnected i {
    font-size: 2.5rem;
    color: #f59e0b;
    margin-bottom: 4px;
}
